import{_ as a,o as i,c as t,a5 as e}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"第8章 OSの仕組み","description":"","frontmatter":{"title":"第8章 OSの仕組み","study":{"source":"IT教本","status":"outline","summary":"プロセス・スレッド・仮想メモリ・システムコール・I/Oを学ぶ順序と観察課題をまとめた学習計画・概要です。OS各機構の専用詳解はまだ揃っていません。このページの概説と章末の資料を足場に、手元のOSで挙動を確かめます。\\n\\n## 関連する辞典本文・実践\\n\\n- [アロケータ](/runtime/me","section":"learning","format":"path","domain":"os","collection":"low-level","order":9}},"headers":[],"relativePath":"guide/low-level/operating-system.md","filePath":"guide/low-level/operating-system.md"}'),n={name:"guide/low-level/operating-system.md"};function r(s,l,o,d,c,u){return i(),t("div",null,[...l[0]||(l[0]=[e(`<div id="第8章-os-──-プロセス・スレッド・仮想メモリ・システムコール" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第8章-osの仕組み" tabindex="-1">第8章 OSの仕組み <a class="header-anchor" href="#第8章-osの仕組み" aria-label="Permalink to &quot;第8章 OSの仕組み&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>プロセス・スレッド・仮想メモリ・システムコール・I/Oを学ぶ順序と観察課題をまとめた<strong>学習計画・概要</strong>です。OS各機構の専用詳解はまだ揃っていません。このページの概説と章末の資料を足場に、手元のOSで挙動を確かめます。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a>で、アプリ側の領域管理とOSへの要求を区別できます。</li><li><a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a>は、共有データを扱う際の問題を調べる入口です。仮想メモリやスケジューラ全体の説明を代替する記事ではありません。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>ゲームは必ずOSの上で走る(コンソールでも薄いOSがある)。 パッド入力は<strong>割り込みとドライバ</strong>が、ロード画面は<strong>ファイルI/Oと ページキャッシュ</strong>が、ジョブシステムは<strong>スレッドとスケジューラ</strong>が、 メモリは<strong>仮想メモリ</strong>が支えている。「なぜ入力に遅延があるのか」 「なぜスレッドを増やしても速くならないのか」に答えられるかは、 この章の理解にかかっている。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>カーネル/ユーザーモード、システムコールの仕組みを説明できる</li><li>プロセスとスレッドの違い、コンテキストスイッチのコストを説明できる</li><li>仮想メモリ(ページング、ページテーブル、TLB、ページフォルト)を説明できる</li><li>排他制御(ミューテックス、アトミック、ロックフリーの概念)を使い分けられる</li><li>割り込み→ドライバ→アプリというパッド入力の経路を説明できる</li><li>ジョブシステムの設計原理を説明できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第2〜4章(CPU・メモリ・アセンブリ)、第7章(実行ファイル)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>OSの役割とカーネル/ユーザーモード</strong><ul><li>ここではWindows/x86-64を主な例にする。ring0/ring3はx86の特権レベルの呼称。 アプリからの特権操作はOSが管理する。許可されたデバイスのマッピングや ユーザーモードドライバもあり、「ハードアクセスは全てカーネル内」とは限らない</li><li><strong>システムコール</strong>: x86-64ではsyscall命令等を通じてカーネルの処理を要求する。 遷移と要求処理にはコストがあり、CPU・OS・要求内容で変わる。必要ならまとめて計測する</li><li>Win32 API → ntdll → カーネルという層構造</li></ul></li><li><strong>プロセス</strong><ul><li>プロセス = 仮想アドレス空間 + リソース + スレッド群</li><li>EXE起動の流れ: CreateProcess → PEローダ → DLL解決 → メインスレッド開始 (第7章の実行ファイル知識がここで回収される)</li><li>プロセスのアドレス空間は通常隔離される。共有メモリや、権限を持つ デバッガ等による他プロセスの読取り/書込みは、OSの仕組みを通じて行う</li></ul></li><li><strong>仮想メモリ(最重要)</strong><ul><li>仮想アドレス→物理アドレスの変換。ページ、ページテーブル、TLB。 4KiBは一般的なx86-64環境の基本ページの例。サイズはOS/構成に依存し、 WindowsではGetSystemInfoのdwPageSize等で確認する(予約時の粒度とは別)</li><li><strong>メリット</strong>: プロセス隔離/連続に見える空間/メモリ保護(ヌルポでAV)/ デマンドページング/メモリマップドファイル</li><li>ページフォルト: 遅延割り当てやデータの読込み等でOSが処理できる場合と、 不正なアドレス/保護違反等でAccess Violationに至る場合を分ける → <strong>0xC0000005はOSの保護機構がバグを検出してくれた瞬間</strong></li><li>VirtualAlloc(予約/コミットの2段階)── 大型ゲームのメモリ戦略</li><li>メモリマップドファイル ── アセットストリーミングの基盤技術</li><li>TLBミスとヒュージページ(大規模ゲームの最適化)</li></ul></li><li><strong>スレッドとスケジューリング</strong><ul><li>スレッド = 実行文脈(レジスタ+スタック)。同一プロセス内でメモリ共有</li><li>プリエンプティブスケジューリング、タイムスライス、優先度</li><li><strong>コンテキストスイッチのコスト</strong>と、キャッシュ/TLBへの影響。時間は環境による。 CPU負荷が高いworkerは利用可能なCPU数を出発点に計測し、メイン/描画thread、 SMT、I/O待ち、ジョブ粒度も考慮する。総スレッド数の最適値が常にコア数とは限らない</li><li>CPUアフィニティ(コンソール開発ではコア割り当てを明示することも)</li></ul></li><li><strong>同期と並行性(ゲーム実務の核心)</strong><ul><li>データ競合とは何か(未定義動作)</li><li>ミューテックス/クリティカルセクション、条件変数、セマフォ</li><li><strong>アトミック操作</strong>(lock cmpxchg等のCPU命令が正体)</li><li>デッドロック(ロック順序)、優先度逆転</li><li>メモリオーダー(acquire/release)は「存在と怖さ」を知る程度でよい</li><li><strong>ゲームのジョブシステム</strong>: スレッドプール+ワークスティーリング+ フレームを小さなジョブに分割(UE Tasks / Unity C# JobSystem の原理)</li></ul></li><li><strong>割り込みとデバイスドライバ、入力の経路</strong><ul><li>ハードウェア割り込み → カーネルのハンドラ → ドライバ</li><li>USBはポーリングベース(パッドは125Hz〜1000Hz)</li><li>パッド入力の全経路: パッド内マイコン → USB/BT → HIDドライバ → (XInput/GameInput) → ゲームのポーリング → 今フレームの入力として消費</li><li><strong>入力遅延の分解</strong>: パッドスキャン+USBポーリング+OS+ ゲームループの待ち+表示遅延</li></ul></li><li><strong>ファイルI/Oと時間</strong><ul><li>同期I/O vs 非同期I/O(Overlapped/IOCP)── ストリーミングの基盤</li><li>ページキャッシュ(2回目のロードが速い理由)</li><li>高精度タイマ QueryPerformanceCounter(第14章で使用)</li></ul></li><li><strong>(演習として)OS自作という選択肢</strong><ul><li>『ゼロからのOS自作入門』は最高の理解をくれるが時間も莫大。 本教本では<strong>任意課題</strong>とし、MikanOSの序盤(ブート〜画面描画)だけでも 価値があると付記する</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>仮想メモリ</strong> ── 現代OSの中心発明。AVも隔離もストリーミングもこれ</li><li><strong>OSへの要求にもコストがある</strong> ── 呼出し回数・要求内容・待機を測り、必要ならバッチングする</li><li><strong>スレッドは無料ではない</strong> ── コンテキストスイッチ・同期コスト</li><li><strong>データ競合=UB</strong> ── 「たまに壊れるマルチスレッドバグ」の正体</li><li><strong>入力はポーリングで刻まれている</strong> ── 遅延理解の鍵</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>Access Violation (0xC0000005)</td><td>仮想メモリの保護</td></tr><tr><td>ロード最適化・アセットストリーミング</td><td>非同期I/O・mmap・ページキャッシュ</td></tr><tr><td>ジョブシステム/ワーカースレッド設計</td><td>スレッド・同期・ワークスティーリング</td></tr><tr><td>「たまに壊れる」マルチスレッドバグ</td><td>データ競合・アトミック</td></tr><tr><td>入力遅延の計測と削減</td><td>USBポーリング・割り込み・経路分解</td></tr><tr><td>ヒッチ(スパイク)の原因がOS側</td><td>ページフォルト・スケジューラ</td></tr><tr><td>コンソールの厳しいメモリ管理</td><td>VirtualAllocの予約/コミット</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li><code>VirtualAlloc</code>で1GBを<strong>予約</strong>し、少しずつ<strong>コミット</strong>して使うプログラムを 書け。タスクマネージャの「コミット済み」と「ワーキングセット」の違いを観察。</li><li>わざとnullptrに書き込み、VSで例外コード0xC0000005を確認。 「なぜOSはこれを検出できるのか」をページテーブルの言葉で説明せよ。</li><li>スレッド8本で共有カウンタを (a)保護なし (b)mutex (c)atomic で インクリメントし、結果と速度を比較せよ。(a)の値が狂う理由を説明せよ。</li><li><strong>ミニジョブシステム</strong>: スレッドプール+ジョブキュー(mutex+条件変数)を 実装し、1万個の粒子更新をジョブ分割して並列化せよ。コア数と スループットの関係を計測せよ。</li><li><code>XInputGetState</code>をループで呼び、パッドのボタン状態が変わる様子を コンソール表示せよ(第14章の先取り。10行で書ける)。</li><li>WSLで <code>strace ./a.out</code> を実行し、printfやmallocの裏で走る システムコール(write, mmap, brk)を観察せよ。</li><li>大きなファイルの読み込みを1回目と2回目で計測し、ページキャッシュの 効果を確認せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li><strong>&quot;Operating Systems: Three Easy Pieces (OSTEP)&quot;</strong> ── 無料Web公開・ 邦訳あり。仮想化/並行性/永続化の3部構成が美しい。この章の主教材</li><li>『Windowsの仕組み(Windows Internals 第7版)』── 辞書として。 プロセス・メモリ・I/O章を拾い読み</li><li>『ゼロからのOS自作入門』内田公太 ── OSの実装を追う任意課題</li><li>『詳解Linuxカーネル』── 発展編送りでよい</li><li>『[試して理解]Linuxのしくみ』武内覚 ── 手を動かす系の良書(WSLで)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>MikanOS</strong>(uchan-nos/mikanos)── 日本語で読める教育用OS</li><li>xv6(MIT)── 1万行のUNIX。プロセス・システムコールの実装が読める</li><li>Wine のXInput実装(パッド入力の中身が覗ける)</li><li>marl(google/marl)── ゲーム向き協調スケジューラ/ファイバー</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>OSTEPの著者講義(YouTube)</li><li>CppCon &quot;C++ atomics, from basic to advanced&quot;(Fedor Pikus)</li><li>GDC &quot;Parallelizing the Naughty Dog Engine Using Fibers&quot; ── ジョブシステム講演の金字塔。<strong>必見</strong></li><li>Molecular Matters等のジョブシステム解説ブログ(Job System 2.0)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>xv6 の <code>proc.c</code>(コンテキストスイッチ)、<code>vm.c</code>(ページテーブル)</li><li>marl のスケジューラ</li><li>UE5 <code>Engine/Source/Runtime/Core/Private/HAL/</code> のスレッド抽象 (<code>FRunnableThreadWin</code> など)── Win32 APIの薄い包装だと分かる</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>システムコールは通常の関数呼出しと何が違うか。遷移・要求処理・待機のコストを区別できるか。</li><li>仮想メモリの利点を4つ挙げよ。Access Violationはどう検出されるか。</li><li>プロセスとスレッドの違いは? ゲームが1プロセス多スレッドなのはなぜ?</li><li>データ競合とは何か。mutexとatomicの使い分けは?</li><li>CPU中心のジョブのworker数をCPU数から検討する理由と、常にその数が最適とは限らない条件は?</li><li>パッドのボタン押下がゲームに届くまでの経路を、割り込み/ポーリング/ ドライバの言葉で説明せよ。</li><li>ロード時間の2回目が速いのはなぜか。</li><li>ジョブシステムはなぜ「スレッドを毎回作る」設計にしないのか。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             ┌─────────── ゲームプロセス ───────────┐</span></span>
<span class="line"><span> パッド ──USB─→ [HIDドライバ] ─→ XInput ─→ 入力ポーリング   │</span></span>
<span class="line"><span>             │                     (メインスレッド)        │</span></span>
<span class="line"><span> ディスク ──→ [ファイルI/O/ページキャッシュ] ─→ 非同期ロード │</span></span>
<span class="line"><span>             │                     (ストリーミングスレッド) │</span></span>
<span class="line"><span>             │  [ジョブシステム] ワーカー×Nコア              │</span></span>
<span class="line"><span>             │   物理/アニメ/カリングを並列実行              │</span></span>
<span class="line"><span>             │  [仮想メモリ] 全確保の土台(VirtualAlloc)     │</span></span>
<span class="line"><span>             └─────────────┬───────────────────────┘</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>              [GPUドライバ(カーネル)] ─→ GPU (第11-13章)</span></span>
<span class="line"><span> スケジューラが全スレッドをコアに配置 / AVはページ保護が検出</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/gettingstarted/user-mode-and-kernel-mode" target="_blank" rel="noreferrer">Microsoft: User mode and kernel mode</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/api/sysinfoapi/ns-sysinfoapi-system_info" target="_blank" rel="noreferrer">Microsoft: SYSTEM_INFO — page size and allocation granularity</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space" target="_blank" rel="noreferrer">Microsoft: Virtual Address Space</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/procthread/scheduling-priorities" target="_blank" rel="noreferrer">Microsoft: Scheduling Priorities</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 64 and IA-32 Architecture / Optimization manuals</a></li></ul>`,35)])])}const g=a(n,[["render",r]]);export{p as __pageData,g as default};
